    d = (a - m) / b
    if m != 0 {
        if (b < 0) != (m < 0) {
            m = m + b
            d = d - 1.0
        }
    }
    else {
        m = py_zero_f(b)
    }
    if k == 1 {
        return m
    }
    if d != 0 {
        f = floor(d)
        if d - f > 0.5 {
            f = f + 1.0
        }
        return f
    }
    return py_zero_f(a / b)
}

#| a % b of two ints.
def py_mod_i(a, b) {
    if b == 0 {
        stop("ZeroDivisionError: integer modulo by zero")
    }
