# @@ shift one letter
ALPHABET = 26
def shift_char(c, k) {
    if "a" <= c and c <= "z" {
        return chr(py_int(py_mod_i(py_int(py_int(ord(c) - ord("a")) + k), ALPHABET) + ord("a")))
    }
    if "A" <= c and c <= "Z" {
        return chr(py_int(py_mod_i(py_int(py_int(ord(c) - ord("A")) + k), ALPHABET) + ord("A")))
    }
    return c
}
# @@ shift a message
def caesar(text_, k) {
    return join("", [shift_char(py_c3, k) for py_c3 in text_])
}
